{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be a dictionary")
    payload = case.get("payload", case)
    if not isinstance(payload, dict):
        raise ValueError("payload must be a dictionary")

    nodes = payload.get("nodes")
    required_symbols = payload.get("required_symbols")
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if not isinstance(required_symbols, list):
        raise ValueError("required_symbols must be a list")
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError("required_symbols must contain strings")
    if len(set(required_symbols)) != len(required_symbols):
        raise ValueError("required_symbols must be unique")

    by_id = {}
    children = {}
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be a dictionary")
        required_fields = ("id", "parent", "symbol", "depth", "removable", "utility")
        if any(field not in node for field in required_fields):
            raise ValueError("node is missing a required field")
        node_id = node["id"]
        if not isinstance(node_id, str) or not node_id or node_id in by_id:
            raise ValueError("node ids must be unique non-empty strings")
        if node["parent"] is not None and not isinstance(node["parent"], str):
            raise ValueError("parent must be a node id or null")
        if not isinstance(node["symbol"], str):
            raise ValueError("symbol must be a string")
        if isinstance(node["depth"], bool) or not isinstance(node["depth"], int) or node["depth"] < 0:
            raise ValueError("depth must be a non-negative integer")
        if not isinstance(node["removable"], bool):
            raise ValueError("removable must be boolean")
        utility = node["utility"]
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("utility must be finite")
        by_id[node_id] = node
        children[node_id] = []

    roots = []
    for node_id, node in by_id.items():
        parent = node["parent"]
        if parent is None:
            roots.append(node_id)
        else:
            if parent not in by_id or parent == node_id:
                raise ValueError("node parent is invalid")
            children[parent].append(node_id)
    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    root_id = roots[0]
    if by_id[root_id]["depth"] != 0:
        raise ValueError("root depth must be zero")

    for node_id, node in by_id.items():
        if node_id == root_id:
            continue
        parent = node["parent"]
        if by_id[parent]["depth"] + 1 != node["depth"]:
            raise ValueError("node depths must match tree structure")

    seen = set()
    stack = [root_id]
    while stack:
        node_id = stack.pop()
        if node_id in seen:
            raise ValueError("tree contains a cycle")
        seen.add(node_id)
        stack.extend(children[node_id])
    if len(seen) != len(by_id):
        raise ValueError("tree contains disconnected nodes")

    symbol_counts = {}
    for node in nodes:
        symbol = node["symbol"]
        symbol_counts[symbol] = symbol_counts.get(symbol, 0) + 1
    if any(symbol_counts.get(symbol, 0) == 0 for symbol in required_symbols):
        raise ValueError("required symbol is not represented")

    candidate_order = sorted(
        (node_id for node_id, node in by_id.items() if node_id != root_id and node["removable"]),
        key=lambda node_id: (-by_id[node_id]["depth"], node_id),
    )

    retained = set(by_id)
    removal_order = []
    for node_id in candidate_order:
        node = by_id[node_id]
        if any(child_id in retained for child_id in children[node_id]):
            continue
        symbol = node["symbol"]
        if symbol in required_symbols and symbol_counts[symbol] <= 1:
            continue
        retained.remove(node_id)
        symbol_counts[symbol] -= 1
        removal_order.append(node_id)

    retained_ids = sorted(retained)
    retained_utility = math.fsum(float(by_id[node_id]["utility"]) for node_id in retained_ids)
    removed_utility = math.fsum(float(by_id[node_id]["utility"]) for node_id in removal_order)

    return {
        "retained_ids": retained_ids,
        "removal_order": removal_order,
        "grammar_valid": True,
        "interestingness_preserved": True,
        "registered_candidate_order": candidate_order,
        "stable_ties": True,
        "retained_utility": retained_utility,
        "removed_utility": removed_utility,
    }
"}
